import EventEmitter from 'node:events';
function main(): void {
  const E: any = EventEmitter;
  // an instance that never ran the constructor (native addons and mixins inherit like this)
  const o: any = Object.create(E.prototype);
  o.on('open', () => console.log('open fired'));
  o.once('open', () => console.log('once fired'));
  console.log(o.emit('open'), o.listenerCount('open'), o.eventNames().join(), Object.keys(o).join());
  const p: any = {};
  Object.setPrototypeOf(p, E.prototype);
  console.log(p.emit('nothing'), p.listeners('x').length, p.eventNames().length, p.removeAllListeners().constructor === undefined);
  p.on('x', () => {});
  console.log(p.listenerCount('x'), p._eventsCount);
  p.removeAllListeners('x');
  console.log(p.listenerCount('x'));
}
